select race_date,track,race_no,frozen_at,protocol_version,model_label,payload->'audit'->>'score_method' score_method,payload->'audit'->>'score_engine_id' score_engine_id,(select array_agg(k order by k) from jsonb_object_keys(payload->'audit') k) audit_keys,jsonb_array_length(payload->'runners') runners from public.official_predictions where circuit='JRA' and status='FROZEN' and race_date in ('2026-11-16','2026-11-21') order by race_date,frozen_at,track,race_no
